import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Vật lý","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/vat-ly.md","filePath":"ideas/inquiry-ib/vat-ly.md"}'),o={name:"ideas/inquiry-ib/vat-ly.md"};function g(c,n,u,e,r,l){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="vat-ly" tabindex="-1">Vật lý <a class="header-anchor" href="#vat-ly" aria-label="Permalink to &quot;Vật lý&quot;">​</a></h1><p>Trên trang này# Vật lý — ba bài học inquiry theo IB <a href="#vat-ly-—-ba-bai-hoc-inquiry-theo-ib">​</a> Vật lý là môn mà học sinh mang sẵn rất nhiều <strong>niềm tin sai</strong> vào lớp — những quy luật tự rút ra từ đời sống hằng ngày, hợp lý nhưng sai. Inquiry trong Vật lý mạnh nhất ở chỗ này: nó tạo ra tình huống mà niềm tin sai tự nó vỡ. Ý xuyên suốt cả mônCái ta thấy hằng ngày không phải quy luật. Nó là quy luật cộng thêm ma sát, không khí, lực cản — vật lý bắt đầu khi tách được những tác động chồng lên nhau đó. Cũng quan trọng — nhưng không phải ý lớn nhất- Trở ngại lớn nhất không phải thiếu thông tin, mà là những quy luật sai learner đã tự xây từ kinh nghiệm sống.</p><ul><li>Một định luật chỉ có nghĩa khi nói rõ nó áp cho hệ nào.</li><li>Đã đo là có sai số. Một con số không kèm sai số là con số chưa hoàn chỉnh.</li></ul><h2 id="demo-1-—-ma-sat-vi-sao-vat-dung-lai-​" tabindex="-1">Demo 1 — Ma sát: vì sao vật dừng lại? <a href="#demo-1-—-ma-sat-vi-sao-vat-dung-lai">​</a> <a class="header-anchor" href="#demo-1-—-ma-sat-vi-sao-vat-dung-lai-​" aria-label="Permalink to &quot;Demo 1 — Ma sát: vì sao vật dừng lại? [​](#demo-1-—-ma-sat-vi-sao-vat-dung-lai)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Systems<strong>Related concepts</strong>Interaction · Evidence · Models<strong>Global context</strong>Scientific and technical innovation<strong>Statement of inquiry</strong>Những gì ta quan sát hằng ngày có thể dẫn tới kết luận sai nếu ta không tách được các tác động đồng thời.<strong>Cần biết trước</strong>Lực, đơn vị newton, cách vẽ mũi tên lực</p><h3 id="ba-cau-hoi-​" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-cau-hoi-​" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Ma sát là gì? Nó phụ thuộc vào những yếu tố nào?</li><li><strong>Conceptual:</strong> Vì sao một vật đang chuyển động lại dừng nếu không có gì đẩy ngược?</li><li><strong>Debatable:</strong> Ma sát là thứ nên loại bỏ hay nên tận dụng?</li></ul><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Lôi ra niềm tin sai (6 phút).</strong> Giáo viên đẩy một cuốn sách trên bàn. Nó trượt rồi dừng. <em>&quot;Vì sao nó dừng?&quot;</em> Câu trả lời gần như luôn xuất hiện: <em>&quot;Vì hết lực đẩy.&quot;</em> Giáo viên ghi câu đó lên bảng, nguyên văn, <strong>không bình luận</strong>. <em>&quot;Đây là giả thuyết của lớp. Ta sẽ kiểm tra nó.&quot;</em> Việc ghi nguyên văn quan trọng: nó biến niềm tin thành một đối tượng có thể kiểm tra, thay vì một cảm giác mơ hồ trong đầu. <strong>Bước 2 — Thí nghiệm phá giả thuyết (12 phút).</strong> Ba mặt: bàn gỗ · khăn vải · một tấm kính có xịt nước xà phòng. Cùng một cuốn sách, cùng một lực đẩy (dùng một lò xo đơn giản để lực gần như nhau). Học sinh đo quãng đường trượt: MặtQuãng đườngKhăn vải12 cmBàn gỗ47 cmKính trơn190 cm*&quot;Lực đẩy như nhau cả ba lần. Vậy nếu vật dừng vì &#39;hết lực đẩy&#39;, vì sao ba quãng đường lại khác nhau?&quot;* Đây là chỗ giả thuyết ban đầu vỡ — và nó vỡ bằng dữ liệu của chính học sinh, không phải bằng lời giáo viên. <strong>Bước 3 — Đẩy ngoại suy (10 phút).</strong><em>&quot;Nếu mặt càng trơn thì càng đi xa — thì mặt trơn hoàn hảo, không có ma sát, sẽ thế nào?&quot;</em> Học sinh tự đi tới: <em>&quot;Đi mãi.&quot;</em><em>&quot;Vậy ai đúng: các em lúc đầu, hay các em bây giờ?&quot;</em><strong>Bước 4 — Đặt tên (5 phút).</strong> Giáo viên đưa ngôn ngữ chính xác: lực ma sát, định luật I Newton, quán tính. Học sinh nhận ra định luật I không phải một điều khó tin — nó chính là kết luận các em vừa tự rút ra. <strong>Bước 5 — Điều tra tiếp, học sinh tự thiết kế (15 phút).</strong><em>&quot;Ma sát phụ thuộc vào những gì? Chọn một yếu tố, thiết kế thí nghiệm kiểm tra nó.&quot;</em> Các nhóm chọn: khối lượng · diện tích tiếp xúc · tốc độ. Nhóm chọn &quot;diện tích tiếp xúc&quot; thường ngạc nhiên với kết quả — và đó là bài học phụ rất giá trị: kết quả bất ngờ là dữ liệu, không phải sai sót. Giáo viên chỉ hỏi một câu ở bước này: <em>&quot;Em thay đổi cái gì, và em giữ nguyên những cái gì?&quot;</em> — đây chính là khái niệm biến độc lập và biến kiểm soát, được học từ nhu cầu thật.</p><h3 id="cham-theo-tieu-chi-​" tabindex="-1">Chấm theo tiêu chí <a href="#cham-theo-tieu-chi">​</a> <a class="header-anchor" href="#cham-theo-tieu-chi-​" aria-label="Permalink to &quot;Chấm theo tiêu chí [​](#cham-theo-tieu-chi)&quot;">​</a></h3><p>Tiêu chíỞ bài này<strong>A — Knowing &amp; understanding</strong>Giải thích được ma sát và định luật I<strong>B — Inquiring &amp; designing</strong>Thiết kế thí nghiệm có biến kiểm soát rõ ràng<strong>C — Processing &amp; evaluating</strong>Xử lý số liệu, nhận ra sai số, đánh giá độ tin cậy<strong>D — Reflecting on impacts</strong>Bàn về ma sát trong phanh xe, lốp, thiết kế ổ bi</p><h2 id="demo-2-—-đinh-luat-iii-newton-cap-luc-ma-khong-ai-tin-​" tabindex="-1">Demo 2 — Định luật III Newton: cặp lực mà không ai tin <a href="#demo-2-—-đinh-luat-iii-newton-cap-luc-ma-khong-ai-tin">​</a> <a class="header-anchor" href="#demo-2-—-đinh-luat-iii-newton-cap-luc-ma-khong-ai-tin-​" aria-label="Permalink to &quot;Demo 2 — Định luật III Newton: cặp lực mà không ai tin [​](#demo-2-—-đinh-luat-iii-newton-cap-luc-ma-khong-ai-tin)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Relationships<strong>Related concepts</strong>Interaction · Force · Evidence<strong>Global context</strong>Scientific and technical innovation<strong>Statement of inquiry</strong>Mọi tương tác đều có hai chiều, kể cả khi kết quả nhìn thấy chỉ ở một phía.<strong>Cần biết trước</strong>Lực, khối lượng, gia tốc, định luật II</p><h3 id="ba-cau-hoi-​-1" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi-1">​</a> <a class="header-anchor" href="#ba-cau-hoi-​-1" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi-1)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Định luật III Newton phát biểu thế nào?</li><li><strong>Conceptual:</strong> Nếu hai lực bằng nhau và ngược chiều, vì sao vật vẫn chuyển động?</li><li><strong>Debatable:</strong> Vì sao một định luật đơn giản như vậy lại khó tin đến thế?</li></ul><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Câu hỏi bẫy (5 phút).</strong><em>&quot;Một xe tải đâm vào một xe máy. Xe nào chịu lực lớn hơn?&quot;</em> Bỏ phiếu. Gần như cả lớp chọn xe máy. Giáo viên ghi lại tỷ lệ, không bình luận. <strong>Bước 2 — Đo thật (15 phút).</strong> Hai lực kế móc vào nhau. Hai học sinh kéo về hai phía — một em kéo mạnh, một em kéo yếu, một em thậm chí không kéo mà chỉ giữ. Học sinh đọc số trên cả hai lực kế. Chúng <strong>luôn bằng nhau</strong>, trong mọi tình huống. <em>&quot;Thử làm cho hai số khác nhau đi. Nhóm nào làm được?&quot;</em> Cả lớp thử đủ cách trong vài phút. Không nhóm nào làm được. Đây là một trong những khoảnh khắc thuyết phục nhất mà một tiết Vật lý có thể tạo ra. <strong>Bước 3 — Mâu thuẫn với trực giác (10 phút).</strong><em>&quot;Vậy quay lại xe tải và xe máy: lực bằng nhau. Nhưng vì sao xe máy nát còn xe tải chỉ móp?&quot;</em> Học sinh vật lộn ở đây. Giáo viên đưa một gợi ý, không đưa đáp án: <em>&quot;Cùng một lực, nhưng hai vật khác nhau ở chỗ nào?&quot;</em> Ai đó sẽ nhớ ra định luật II: F = ma. Cùng F, khác m, thì khác a. <strong>Bước 4 — Chỗ khó thật (10 phút).</strong><em>&quot;Nếu lực luôn theo cặp bằng nhau và ngược chiều, vì sao có gì chuyển động được? Chúng phải triệt tiêu chứ?&quot;</em> Đây là câu hỏi khó nhất và cũng là chỗ hiểu lầm sâu nhất. Giáo viên để học sinh vẽ sơ đồ lực, rồi hỏi: <em>&quot;Hai lực đó tác dụng lên cùng một vật, hay lên hai vật khác nhau?&quot;</em> Khoảnh khắc học sinh nhận ra hai lực nằm trên <strong>hai vật khác nhau</strong> nên không triệt tiêu nhau — đó là điểm chuyển của cả bài học. <strong>Bước 5 — Ứng dụng (10 phút).</strong><em>&quot;Tên lửa bay trong vũ trụ, không có gì để đẩy vào. Nó đẩy vào cái gì?&quot;</em></p><h2 id="demo-3-—-nang-luong-no-đi-đau-​" tabindex="-1">Demo 3 — Năng lượng: nó đi đâu? <a href="#demo-3-—-nang-luong-no-đi-đau">​</a> <a class="header-anchor" href="#demo-3-—-nang-luong-no-đi-đau-​" aria-label="Permalink to &quot;Demo 3 — Năng lượng: nó đi đâu? [​](#demo-3-—-nang-luong-no-đi-đau)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Change<strong>Related concepts</strong>Transformation · Conservation · Energy<strong>Global context</strong>Globalization and sustainability<strong>Statement of inquiry</strong>Năng lượng không mất đi mà đổi dạng, và mỗi lần đổi dạng đều có phần trở nên khó dùng lại.<strong>Cần biết trước</strong>Các dạng năng lượng, công thức thế năng và động năng</p><h3 id="ba-cau-hoi-​-2" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi-2">​</a> <a class="header-anchor" href="#ba-cau-hoi-​-2" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi-2)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Có những dạng năng lượng nào? Thế năng tính thế nào?</li><li><strong>Conceptual:</strong> Nếu năng lượng được bảo toàn, vì sao quả bóng nảy ngày càng thấp?</li><li><strong>Debatable:</strong> &quot;Tiết kiệm năng lượng&quot; có nghĩa gì, nếu năng lượng vốn không mất đi?</li></ul><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Hiện tượng quen thuộc, câu hỏi lạ (5 phút).</strong> Thả một quả bóng từ độ cao 1m. Nó nảy lên 60cm, rồi 36cm, rồi 20cm… <em>&quot;Bảo toàn năng lượng nói năng lượng không mất đi. Vậy phần thiếu đi đâu?&quot;</em><strong>Bước 2 — Thu số liệu (12 phút).</strong> Nhóm đo độ cao mỗi lần nảy của ba loại bóng: bóng tennis, bóng cao su cứng, bóng nhựa rỗng. Lập bảng và vẽ đồ thị. Học sinh nhận ra tỷ lệ nảy khá ổn định với mỗi loại bóng — một quy luật các em tự tìm ra. <strong>Bước 3 — Truy tìm phần thiếu (15 phút).</strong><em>&quot;Liệt kê mọi thứ có thể nhận phần năng lượng đó.&quot;</em> Nhóm đề xuất: âm thanh (nghe được tiếng bóng chạm sàn), nhiệt (bóng nóng lên?), biến dạng của bóng, rung động của sàn. <em>&quot;Kiểm tra được cái nào?&quot;</em> Nhóm thường chọn nhiệt: bóp mạnh một quả bóng cao su liên tục 30 giây rồi áp lên má. Nó ấm lên rõ rệt. Đây là bằng chứng trực tiếp và học sinh nhớ rất lâu. <strong>Bước 4 — Khái niệm khó (8 phút).</strong> Giáo viên đưa khái niệm <strong>năng lượng suy giảm chất lượng</strong>: năng lượng không mất, nhưng khi đã tán thành nhiệt phân tán ra môi trường thì gần như không thu lại được để làm việc có ích. <strong>Bước 5 — Tranh luận (10 phút).</strong><em>&quot;Vậy &#39;tiết kiệm điện&#39; thật ra nghĩa là gì? Điện có mất đi đâu?&quot;</em> Học sinh dần đi tới một hiểu biết chính xác hơn nhiều so với khẩu hiệu: ta không tiết kiệm năng lượng, ta tiết kiệm <strong>năng lượng ở dạng dùng được</strong>.</p><h3 id="vi-sao-ba-demo-nay-co-cau-truc-giong-nhau-​" tabindex="-1">Vì sao ba demo này có cấu trúc giống nhau <a href="#vi-sao-ba-demo-nay-co-cau-truc-giong-nhau">​</a> <a class="header-anchor" href="#vi-sao-ba-demo-nay-co-cau-truc-giong-nhau-​" aria-label="Permalink to &quot;Vì sao ba demo này có cấu trúc giống nhau [​](#vi-sao-ba-demo-nay-co-cau-truc-giong-nhau)&quot;">​</a></h3><p>Cả ba đều theo một khuôn: <strong>lôi niềm tin sai ra → tạo dữ liệu phá nó → để học sinh tự rút kết luận → đặt tên chính xác → mở rộng</strong>. Đây không phải ngẫu nhiên. Trong Vật lý, thứ cản trở việc học không phải sự thiếu thông tin — mà là những quy luật sai học sinh đã tự xây từ kinh nghiệm sống. Giảng thẳng thường không gỡ được chúng: học sinh sẽ ghi nhớ lời thầy như một lớp phủ, còn quy luật cũ vẫn nguyên vẹn bên dưới và sẽ quay lại ngay khi gặp tình huống mới. <a href="/ideas/inquiry-ib/hoa-hoc">Hoá học →</a></p>',25)])])}const b=t(o,[["render",g]]);export{m as __pageData,b as default};
